  user_agent TEXT,
  ip_hash TEXT,
  conversion_value REAL CHECK (conversion_value IS NULL OR typeof(conversion_value) IN ('integer','real')),
  commission_earned REAL CHECK (commission_earned IS NULL OR typeof(commission_earned) IN ('integer','real')),
  created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (created_at IS NULL OR julianday(created_at) IS NOT NULL),
  CHECK ((event_type IN ('view', 'click', 'conversion'))),
  CHECK ((partner IN ('viator', 'booking', 'getyourguide', 'klook'))),
  PRIMARY KEY (id)
);
CREATE INDEX idx_affiliate_clicks_created ON affiliate_clicks (created_at);
